import argparse
import sys

from .events import count_events, parse_timestamp, read_events


def since_arg(text):
    try:
        return parse_timestamp(text)
    except ValueError:
        raise argparse.ArgumentTypeError(
            f"invalid --since value {text!r}: expected an ISO date or datetime, "
            "e.g. 2024-03-10 or 2024-03-10T12:00:00+00:00"
        )


def build_parser():
    parser = argparse.ArgumentParser(prog="evlog")
    commands = parser.add_subparsers(dest="command", required=True)
    report = commands.add_parser("report", help="count events per service and level")
    report.add_argument("path", help="events file (JSON lines)")
    report.add_argument(
        "--since",
        type=since_arg,
        metavar="WHEN",
        help="only count events at or after this ISO date/datetime (naive values are UTC)",
    )
    return parser


def render(counts):
    lines = [f"{service} {level} {n}" for (service, level), n in sorted(counts.items())]
    lines.append(f"total {sum(counts.values())}")
    return "\n".join(lines)


def main(argv=None, out=None):
    out = out or sys.stdout
    args = build_parser().parse_args(argv)
    if args.command == "report":
        try:
            counts = count_events(read_events(args.path), since=args.since)
        except OSError as exc:
            print(f"evlog: cannot read {args.path}: {exc.strerror}", file=sys.stderr)
            return 1
        except (ValueError, KeyError) as exc:
            print(f"evlog: bad event data in {args.path}: {exc!r}", file=sys.stderr)
            return 1
        print(render(counts), file=out)
    return 0

